15	import com.example.lending.domain.MemberNotFoundException;
16	import org.springframework.stereotype.Service;
17	import org.springframework.transaction.annotation.Transactional;
18	
19	import java.time.LocalDate;
20	
21	@Service
22	@Transactional
23	public class LoanBookService implements LoanBookUseCase {
24	
25	    private final LoadBookPort loadBookPort;
26	    private final SaveBookPort saveBookPort;
27	    private final LoadMemberPort loadMemberPort;
28	    private final LoadLoanPort loadLoanPort;
29	    private final SaveLoanPort saveLoanPort;
30	
31	    public LoanBookService(LoadBookPort loadBookPort, SaveBookPort saveBookPort, LoadMemberPort loadMemberPort,
32	                           LoadLoanPort loadLoanPort, SaveLoanPort saveLoanPort) {
33	        this.loadBookPort = loadBookPort;
34	        this.saveBookPort = saveBookPort;
35	        this.loadMemberPort = loadMemberPort;
36	        this.loadLoanPort = loadLoanPort;
37	        this.saveLoanPort = saveLoanPort;
38	    }
39	
40	    @Override
41	    public Loan loanBook(LoanBookCommand command) {
42	        Book book = loadBookPort.loadBook(command.bookId())
43	                .orElseThrow(() -> new BookNotFoundException(command.bookId()));
44	        Member member = loadMemberPort.loadMember(command.memberId())
45	                .orElseThrow(() -> new MemberNotFoundException(command.memberId()));
46	        if (book.getStatus() == BookStatus.ON_LOAN) {
47	            throw new BookAlreadyOnLoanException(book.getId());
48	        }
49	        member.ensureCanBorrow(loadLoanPort.countLoansByMemberId(member.getId()));
50	        Loan loan = Loan.start(book.getId(), member.getId(), LocalDate.now());
51	        book.setStatus(BookStatus.ON_LOAN);
52	        saveBookPort.saveBook(book);
53	        saveLoanPort.saveLoan(loan);
54	        return loan;
55	    }
56	}
