1	package com.example.lending.architecture;
2	
3	import com.tngtech.archunit.base.DescribedPredicate;
4	import com.tngtech.archunit.core.domain.JavaClass;
5	import com.tngtech.archunit.core.domain.JavaCodeUnit;
6	import com.tngtech.archunit.core.domain.JavaParameter;
7	import com.tngtech.archunit.lang.ArchCondition;
8	import com.tngtech.archunit.lang.ArchRule;
9	import com.tngtech.archunit.lang.CompositeArchRule;
10	import com.tngtech.archunit.lang.ConditionEvents;
11	import com.tngtech.archunit.lang.SimpleConditionEvent;
12	
13	import java.util.List;
14	
15	import static com.tngtech.archunit.base.DescribedPredicate.not;
16	import static com.tngtech.archunit.core.domain.JavaClass.Predicates.resideInAPackage;
17	import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.classes;
18	import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.codeUnits;
19	import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.noClasses;
20	import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.noCodeUnits;
21	import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.noFields;
22	import static com.tngtech.archunit.library.dependencies.SlicesRuleDefinition.slices;
23	
24	/**
25	 * 이 프로젝트의 헥사고날 아키텍처 규칙 R1~R7. 기준 패키지를 인자로 받는다.
26	 * 번호(id)와 이름은 build/arch/lending.json 의 키로 쓰인다.
27	 *
28	 * <p>모든 규칙은 allowEmptyShould(true): 특정 레이어가 아직 없는 코드베이스에서
29	 * "검사 대상 없음"이 위반 1건으로 집계되지 않게 한다. 기준 패키지 오타 방어는 각 테스트가 import 결과를 직접 확인한다.
30	 */
31	public final class HexagonalRules {
32	
33	    public record NamedRule(String id, String name, ArchRule rule) {
34	    }
35	
36	    private static final String ENTITY = "jakarta.persistence.Entity";
37	    private static final String COMPONENT = "org.springframework.stereotype.Component";
38	    private static final String SERVICE = "org.springframework.stereotype.Service";
39	    private static final String JSON_PROPERTY = "com.fasterxml.jackson.annotation.JsonProperty";
40	    private static final String SPRING_BOOT_APPLICATION = "org.springframework.boot.autoconfigure.SpringBootApplication";
41	
42	    private HexagonalRules() {
43	    }
44	
45	    public static List<NamedRule> forBasePackage(String basePackage) {
46	        String domain = basePackage + ".domain..";
47	        String application = basePackage + ".application..";
48	        String adapter = basePackage + ".adapter..";
49	        String adapterIn = basePackage + ".adapter.in..";
50	        String adapterOut = basePackage + ".adapter.out..";
51	        String port = basePackage + ".application.port..";
52	        String portOut = basePackage + ".application.port.out..";
53	
54	        // 도메인은 Bean Validation(jakarta.validation..)과 Jackson(com.fasterxml.jackson..)도 쓰지 않는다
55	        String r1Reason = "domain은 ..application.., ..adapter.., org.springframework.., jakarta.persistence.., "
56	                + "jakarta.validation.., com.fasterxml.jackson..을 의존하지 않는다";
57	        ArchRule r1 = noClasses().that().resideInAPackage(domain)
58	                .should().dependOnClassesThat().resideInAnyPackage(
59	                        application, adapter, "org.springframework..", "jakarta.persistence..",
60	                        "jakarta.validation..", "com.fasterxml.jackson..")
61	                .because(r1Reason)
62	                .allowEmptyShould(true);
63	
64	        ArchRule r2 = noClasses().that().resideInAPackage(application)
65	                .should().dependOnClassesThat().resideInAPackage(adapter)
66	                .because("application은 ..adapter..를 의존하지 않는다")
67	                .allowEmptyShould(true);
68	
69	        String r3Reason = "adapter.in과 adapter.out은 서로 의존하지 않는다";
70	        ArchRule r3 = CompositeArchRule
71	                .of(noClasses().that().resideInAPackage(adapterIn)
72	                        .should().dependOnClassesThat().resideInAPackage(adapterOut)
73	                        .because(r3Reason)
74	                        .allowEmptyShould(true))
75	                .and(noClasses().that().resideInAPackage(adapterOut)
76	                        .should().dependOnClassesThat().resideInAPackage(adapterIn)
77	                        .because(r3Reason)
78	                        .allowEmptyShould(true));
79	
80	        // 최상위 패키지 단위 슬라이스: domain / application / adapter
81	        ArchRule r4 = slices().matching(basePackage + ".(*)..")
82	                .should().beFreeOfCycles()
83	                .because("레이어 간 순환 의존이 없다")
84	                .allowEmptyShould(true);
85	
86	        // @Entity/@Component/@Service는 TYPE 대상이지만 @JsonProperty는 TYPE에 붙을 수 없으므로
87	        // (FIELD/METHOD/PARAMETER/ANNOTATION_TYPE) 클래스 수준 검사만으로는 절대 잡히지 않는다. 멤버·파라미터까지 본다.
88	        String r5Reason = "domain 클래스에 @Entity, @Component, @Service, @JsonProperty가 없다";
89	        ArchRule r5 = CompositeArchRule
90	                .of(noClasses().that().resideInAPackage(domain)
91	                        .should().beAnnotatedWith(ENTITY)
92	                        .orShould().beAnnotatedWith(COMPONENT)
93	                        .orShould().beAnnotatedWith(SERVICE)
94	                        .orShould().beAnnotatedWith(JSON_PROPERTY)
95	                        .because(r5Reason)
96	                        .allowEmptyShould(true))
97	                .and(noFields().that().areDeclaredInClassesThat().resideInAPackage(domain)
98	                        .should().beAnnotatedWith(JSON_PROPERTY)
99	                        .because(r5Reason)
100	                        .allowEmptyShould(true))
101	                .and(noCodeUnits().that().areDeclaredInClassesThat().resideInAPackage(domain)
102	                        .should().beAnnotatedWith(JSON_PROPERTY)
103	                        .because(r5Reason)
104	                        .allowEmptyShould(true))
105	                .and(codeUnits().that().areDeclaredInClassesThat().resideInAPackage(domain)
106	                        .should(notHaveParametersAnnotatedWith(JSON_PROPERTY))
107	                        .because(r5Reason)
108	                        .allowEmptyShould(true));
109	
110	        // record는 포트 계약에 딸린 입력 데이터(예: LoanBookUseCase.LoanBookCommand)라서 interface 요구에서 제외한다.
111	        // record는 상속·구현이 불가능해 포트 역할을 할 수 없으므로 이 예외로 추상 클래스 포트가 빠져나가지 않는다.
112	        String r6Reason = "application.port 아래 타입은 interface이며, port.out 인터페이스의 구현체는 adapter.out에만 있다";
113	        ArchRule r6 = CompositeArchRule
114	                .of(classes().that().resideInAPackage(port)
115	                        .and().areNotAssignableTo(Record.class)
116	                        .should().beInterfaces()
117	                        .because(r6Reason)
118	                        .allowEmptyShould(true))
119	                .and(classes().that().areAssignableTo(resideInAPackage(portOut))
120	                        .and().resideOutsideOfPackage(portOut)
121	                        .should().resideInAPackage(adapterOut)
122	                        .because(r6Reason)
123	                        .allowEmptyShould(true));
124	
125	        // base 직속 클래스 중 @SpringBootApplication 메인 클래스만 예외 (메타 어노테이션 아님, 하위 패키지 아님)
126	        DescribedPredicate<JavaClass> springBootMainClass = DescribedPredicate.describe(
127	                "@SpringBootApplication class directly in " + basePackage,
128	                javaClass -> javaClass.getPackageName().equals(basePackage)
129	                        && javaClass.isAnnotatedWith(SPRING_BOOT_APPLICATION));
130	        ArchRule r7 = classes().that().resideInAPackage(basePackage + "..")
131	                .and(not(springBootMainClass))
132	                .should().resideInAnyPackage(domain, application, adapter)
133	                .because("base 바로 아래의 최상위 패키지는 domain, application, adapter 셋뿐이어야 한다")
134	                .allowEmptyShould(true);
135	
136	        return List.of(
137	                new NamedRule("R1", "domain-no-outward-deps", r1),
138	                new NamedRule("R2", "application-no-adapter-deps", r2),
139	                new NamedRule("R3", "adapters-independent", r3),
140	                new NamedRule("R4", "no-layer-cycles", r4),
141	                new NamedRule("R5", "domain-no-framework-annotations", r5),
142	                new NamedRule("R6", "ports-are-interfaces-implemented-in-adapters", r6),
143	                new NamedRule("R7", "only-three-top-level-packages", r7));
144	    }
145	
146	    private static ArchCondition<JavaCodeUnit> notHaveParametersAnnotatedWith(String annotationName) {
147	        return new ArchCondition<>("not have parameters annotated with @" + annotationName) {
148	            @Override
149	            public void check(JavaCodeUnit codeUnit, ConditionEvents events) {
150	                for (JavaParameter parameter : codeUnit.getParameters()) {
151	                    if (parameter.isAnnotatedWith(annotationName)) {
152	                        events.add(SimpleConditionEvent.violated(codeUnit, String.format(
153	                                "Parameter %d of %s is annotated with @%s",
154	                                parameter.getIndex(), codeUnit.getFullName(), annotationName)));
155	                    }
156	                }
157	            }
158	        };
159	    }
160	}
